<?php
declare(strict_types=1);require __DIR__.'/bootstrap_saas.php';require_once __DIR__.'/passenger_auth_helpers.php';require_once __DIR__.'/saas_feature_helpers.php';
$db=saas_db();$slug=trim((string)($_GET['slug']??''));$token=trim((string)($_GET['token']??''));$tourId=(int)($_GET['tour_id']??0);$accountMode=isset($_GET['account']);$booking=null;
if($accountMode&&passenger_authenticated()){$booking=passenger_booking($tourId);}elseif($slug!==''&&preg_match('/^[a-f0-9]{64}$/',$token)){$q=$db->prepare("SELECT tp.id tp_id,tp.status,tp.fee,tp.discount,pp.id passenger_profile_id,pp.full_name,pp.phone,pp.email,t.id tour_id,t.organization_id,t.name tour_name,t.slug,t.start_date,t.end_date,t.description,o.name organization_name,o.currency FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id JOIN organizations o ON o.id=t.organization_id WHERE t.slug=? AND tp.booking_access_token_hash=? AND tp.booking_access_token_revoked_at IS NULL AND o.status='ACTIVE' LIMIT 1");$q->execute([$slug,hash('sha256',$token)]);$booking=$q->fetch();if(!$booking||$booking['status']!=='ACTIVE'){http_response_code(404);exit('Active booking not found.');}}else{http_response_code(404);exit('Booking link is invalid.');}
$q=$db->prepare("SELECT s.seat_code,b.name bus_name,b.bus_number FROM passenger_seat_assignments psa JOIN seats s ON s.id=psa.seat_id JOIN buses b ON b.id=psa.bus_id WHERE psa.tour_passenger_id=? LIMIT 1");$q->execute([(int)$booking['tp_id']]);$seat=$q->fetch();$q=$db->prepare("SELECT r.room_no,r.room_type FROM room_assignments ra JOIN rooms r ON r.id=ra.room_id WHERE ra.tour_passenger_id=? LIMIT 1");$q->execute([(int)$booking['tp_id']]);$room=$q->fetch();$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_passenger_id=? AND tour_id=?');$q->execute([(int)$booking['tp_id'],(int)$booking['tour_id']]);$paid=(float)$q->fetchColumn();$q=$db->prepare("SELECT id,ticket_number,issued_at FROM ticket_instances WHERE tour_passenger_id=? AND tour_id=? AND status='ISSUED' AND voided_at IS NULL ORDER BY id DESC LIMIT 1");$q->execute([(int)$booking['tp_id'],(int)$booking['tour_id']]);$ticket=$q->fetch();
$features=saas_enabled_features((int)$booking['tour_id']);$featureMap=[];$featureTotal=0;$q=$db->prepare("SELECT tpf.*,tfo.option_label,tfo.option_value FROM tour_passenger_features tpf LEFT JOIN tour_feature_options tfo ON tfo.id=tpf.option_id WHERE tpf.tour_passenger_id=? AND tpf.tour_id=? AND tpf.status='SELECTED'");$q->execute([(int)$booking['tp_id'],(int)$booking['tour_id']]);foreach($q->fetchAll() as $r){$featureMap[(int)$r['tour_feature_id']]=$r;$featureTotal+=(float)$r['total_price'];}
$total=max(0,(float)$booking['fee']-(float)$booking['discount'])+$featureTotal;$due=max(0,$total-$paid);$currency=$booking['currency']?:'BDT';$base=rtrim(dirname((string)($_SERVER['SCRIPT_NAME']??'/')),'/');$qs=$accountMode?'tour_id='.(int)$booking['tour_id'].'&account=1':'slug='.rawurlencode($slug).'&token='.rawurlencode($token);$seatUrl=$base.'/public_seat_select.php?'.$qs;$roomUrl=$base.'/public_room_select.php?'.$qs;$featureUrl=$base.'/public_features.php?'.$qs;$checkoutUrl=$base.'/public_checkout.php?'.$qs;$ticketUrl=$accountMode?$base.'/passenger_ticket.php?ticket_id='.(int)$ticket['id']:$base.'/saas_ticket.php?slug='.rawurlencode($slug).'&token='.rawurlencode($token);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=saas_h($booking['tour_name'])?> — My Booking</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Arial,sans-serif}.hero{background:linear-gradient(135deg,#0f172a,#155eef);color:#fff;padding:42px 20px}.hero-inner,.wrap{width:min(1050px,100%);margin:auto}.hero-inner{padding:0 16px}.hero h1{margin:8px 0;font-size:clamp(30px,5vw,48px)}.wrap{padding:22px 16px 50px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.card{background:#fff;border-radius:16px;padding:20px;box-shadow:0 8px 30px #0000000b;margin-bottom:16px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.stat{padding:14px;border-radius:12px;background:#f8fafc}.label{font-size:12px;color:#667085}.value{font-size:20px;font-weight:800;margin-top:3px}.btn{display:block;text-align:center;text-decoration:none;padding:12px;border-radius:10px;background:#155eef;color:#fff;font-weight:800}.muted{color:#667085;font-size:14px}.paid{color:#067647}.due{color:#b42318}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:#ecfdf3;color:#067647;font-size:12px;font-weight:700}.feature-row{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid #eee}.feature-row:last-child{border-bottom:0}@media(max-width:700px){.grid,.stats{grid-template-columns:1fr}}</style></head><body><header class="hero"><div class="hero-inner"><div><?=saas_h($booking['organization_name'])?></div><h1><?=saas_h($booking['tour_name'])?></h1><p>My Booking</p></div></header><main class="wrap"><section class="card"><h2>Welcome, <?=saas_h($booking['full_name'])?></h2><p><?=saas_h($booking['phone'])?><?=($booking['email']?' · '.saas_h($booking['email']):'')?></p><span class="badge">Booking confirmed</span></section><section class="card"><h2>Booking summary</h2><div class="stats"><div class="stat"><div class="label">Total</div><div class="value"><?=number_format($total,2)?> <?=saas_h($currency)?></div></div><div class="stat"><div class="label">Paid</div><div class="value paid"><?=number_format($paid,2)?> <?=saas_h($currency)?></div></div><div class="stat"><div class="label">Due</div><div class="value <?=($due>0?'due':'paid')?>"><?=number_format($due,2)?> <?=saas_h($currency)?></div></div></div></section><?php if($features):?><section class="card"><h2>Tour options</h2><?php foreach($features as $f):$s=$featureMap[(int)$f['id']]??null;?><div class="feature-row"><div><strong><?=saas_h($f['label'])?></strong><br><span class="muted"><?php if($s&&$f['kind']==='select'):?><?=saas_h($s['option_label']??$s['option_value']??'Selected')?><?php elseif($s):?><?=saas_h($s['value_text'])?><?php else:?>Not selected<?php endif;?></span></div><div><?=($s&&$s['total_price']>0?number_format((float)$s['total_price'],2).' '.saas_h($currency):'')?></div></div><?php endforeach;?><a class="btn" style="margin-top:14px" href="<?=saas_h($featureUrl)?>">Choose / Change options</a></section><?php endif;?><div class="grid"><section class="card"><h2>Seat</h2><p><?=($seat?'<strong>'.saas_h($seat['seat_code']).'</strong> · '.saas_h($seat['bus_name']):'No seat selected yet.')?></p><a class="btn" href="<?=saas_h($seatUrl)?>"><?=($seat?'Change seat':'Select seat')?></a></section><section class="card"><h2>Room</h2><p><?=($room?'<strong>'.saas_h($room['room_no']).'</strong> · '.saas_h($room['room_type']):'No room selected yet.')?></p><a class="btn" href="<?=saas_h($roomUrl)?>"><?=($room?'Change room':'Select room')?></a></section></div><section class="card"><h2>Tour information</h2><p><?=saas_h($booking['start_date'])?><?=($booking['end_date']?' → '.saas_h($booking['end_date']):'')?></p><?php if($booking['description']??''):?><p class="muted"><?=nl2br(saas_h($booking['description']))?></p><?php endif;?></section><section class="card"><h2>Payment</h2><?php if($due>0):?><p class="muted">Outstanding balance: <strong class="due"><?=number_format($due,2)?> <?=saas_h($currency)?></strong></p><a class="btn" href="<?=saas_h($checkoutUrl)?>">Make a payment request</a><?php else:?><p class="paid"><strong>Paid in full.</strong></p><?php endif;?></section><?php if($ticket):?><section class="card"><h2>Your ticket</h2><p><strong><?=saas_h($ticket['ticket_number'])?></strong> · <?=saas_h($ticket['issued_at'])?></p><a class="btn" href="<?=saas_h($ticketUrl)?>">View / Print Ticket</a></section><?php endif;?></main></body></html>